import { expectStatus, test } from "../../fixtures";

test("A vendor's audit trail from another tenant is not found", { tag: "@AUD-02" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor owned by Globex Procurement (the otherTenant persona)
  const member = await apiAs("member");
  const foreignVendor = await factory.vendor({ as: "otherTenant" });

  // Act
  const response = await member.get(`/api/vendors/${foreignVendor.id}/audit`);

  // Assert
  await expectStatus(response, 404);
});
